import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { api } from '../services/api';

const Dashboard: React.FC = () => {
  const { user, logout } = useAuth();
  const [stats, setStats] = useState({
    totalUsers: 0,
    totalParkingAreas: 0,
    totalSlots: 0,
    occupiedSlots: 0,
    availableSlots: 0,
    todayEntries: 0,
    todayExits: 0,
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardStats();
  }, []);

  const fetchDashboardStats = async () => {
    try {
      // Mock data - Replace with actual API call
      const mockStats = {
        totalUsers: 245,
        totalParkingAreas: 8,
        totalSlots: 320,
        occupiedSlots: 245,
        availableSlots: 75,
        todayEntries: 156,
        todayExits: 128,
      };
      setStats(mockStats);
      
      // Actual API call (uncomment when backend is ready):
      // const response = await api.getDashboardStats();
      // if (response.success && response.data) {
      //   setStats(response.data);
      // }
    } catch (error) {
      console.error('Failed to fetch stats:', error);
    } finally {
      setLoading(false);
    }
  };

  const statCards = [
    { title: 'Total Users', value: stats.totalUsers, color: '#64ffda', icon: '👥', change: '+12%' },
    { title: 'Parking Areas', value: stats.totalParkingAreas, color: '#57cbff', icon: '📍', change: '+2' },
    { title: 'Total Slots', value: stats.totalSlots, color: '#ff6b9d', icon: '🚗', change: '320' },
    { title: 'Occupied', value: stats.occupiedSlots, color: '#ffd166', icon: '🟡', change: '76.5%' },
    { title: 'Available', value: stats.availableSlots, color: '#10b981', icon: '🟢', change: '23.5%' },
    { title: 'Today Entries', value: stats.todayEntries, color: '#9d4edd', icon: '📥', change: '+28' },
    { title: 'Today Exits', value: stats.todayExits, color: '#4ecdc4', icon: '📤', change: '+15' },
  ];

  const recentActivities = [
    { user: 'John Doe', action: 'Parked in Zone A-12', time: '10 min ago', type: 'entry' },
    { user: 'Jane Smith', action: 'Exited from Zone B-07', time: '25 min ago', type: 'exit' },
    { user: 'System', action: 'Maintenance alert: Zone C elevator', time: '1 hour ago', type: 'alert' },
    { user: 'Robert Johnson', action: 'New user registration approved', time: '2 hours ago', type: 'user' },
    { user: 'Parking Sensor', action: 'Slot D-15 now available', time: '3 hours ago', type: 'slot' },
  ];

  const getActivityIcon = (type: string) => {
    switch (type) {
      case 'entry': return '📥';
      case 'exit': return '📤';
      case 'alert': return '⚠️';
      case 'user': return '👤';
      case 'slot': return '🚗';
      default: return '📝';
    }
  };

  const getActivityColor = (type: string) => {
    switch (type) {
      case 'entry': return '#10b981';
      case 'exit': return '#3b82f6';
      case 'alert': return '#ef4444';
      case 'user': return '#9d4edd';
      case 'slot': return '#f59e0b';
      default: return '#8892b0';
    }
  };

  return (
    <div className="container" style={{ padding: '20px' }}>
      {/* Header */}
      <div style={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center',
        marginBottom: '40px',
        paddingBottom: '20px',
        borderBottom: '1px solid rgba(100, 255, 218, 0.1)',
      }}>
        <div>
          <h1 style={{ fontSize: '36px', marginBottom: '10px' }}>Dashboard</h1>
          <p style={{ color: '#8892b0', fontSize: '16px' }}>
            Welcome back, <span style={{ color: '#64ffda' }}>{user?.name || 'Admin'}</span>
          </p>
        </div>
        <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
          <Link to="/admin" className="btn btn-secondary">
            Admin Panel
          </Link>
          <button className="btn btn-secondary" onClick={() => logout()}>
            Logout
          </button>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="dashboard-grid">
        {statCards.map((stat, index) => (
          <div key={index} className="card">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
              <div>
                <div style={{ fontSize: '14px', color: '#8892b0', marginBottom: '8px' }}>
                  {stat.title}
                </div>
                <div style={{ fontSize: '32px', fontWeight: 'bold', color: stat.color }}>
                  {stat.value}
                </div>
                <div style={{ fontSize: '12px', color: '#64ffda', marginTop: '8px' }}>
                  {stat.change} from yesterday
                </div>
              </div>
              <div style={{
                width: '50px',
                height: '50px',
                borderRadius: '12px',
                background: `${stat.color}20`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '24px',
              }}>
                {stat.icon}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Charts and Recent Activity */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '40px', marginTop: '40px' }}>
        {/* Parking Occupancy Chart */}
        <div className="card">
          <h3 style={{ fontSize: '20px', marginBottom: '20px', color: '#64ffda' }}>
            Parking Occupancy
          </h3>
          <div style={{ height: '200px', display: 'flex', alignItems: 'flex-end', gap: '20px' }}>
            {[65, 80, 45, 90, 70, 85, 60, 75].map((height, i) => (
              <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                <div style={{
                  width: '100%',
                  height: `${height}%`,
                  background: 'linear-gradient(to top, #64ffda, #57cbff)',
                  borderRadius: '6px 6px 0 0',
                  minHeight: '10px',
                }} />
                <div style={{ fontSize: '12px', color: '#8892b0', marginTop: '8px' }}>
                  Zone {String.fromCharCode(65 + i)}
                </div>
              </div>
            ))}
          </div>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '20px' }}>
            <div style={{ fontSize: '14px', color: '#8892b0' }}>Peak: Zone D (90%)</div>
            <div style={{ fontSize: '14px', color: '#8892b0' }}>Low: Zone C (45%)</div>
          </div>
        </div>

        {/* Recent Activities */}
        <div className="card">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
            <h3 style={{ fontSize: '20px', color: '#64ffda' }}>Recent Activities</h3>
            <Link to="/activities" style={{ fontSize: '14px', color: '#57cbff', textDecoration: 'none' }}>
              View All →
            </Link>
          </div>
          <div style={{ maxHeight: '300px', overflowY: 'auto' }}>
            {recentActivities.map((activity, index) => (
              <div key={index} style={{
                display: 'flex',
                alignItems: 'center',
                padding: '15px 0',
                borderBottom: index < recentActivities.length - 1 ? '1px solid rgba(100, 255, 218, 0.1)' : 'none',
              }}>
                <div style={{
                  width: '40px',
                  height: '40px',
                  borderRadius: '10px',
                  background: `${getActivityColor(activity.type)}20`,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: '18px',
                  color: getActivityColor(activity.type),
                  marginRight: '15px',
                }}>
                  {getActivityIcon(activity.type)}
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ color: '#e6f1ff', fontWeight: '500' as const }}>
                    {activity.user}
                  </div>
                  <div style={{ color: '#8892b0', fontSize: '13px' }}>
                    {activity.action}
                  </div>
                </div>
                <div style={{ color: '#8892b0', fontSize: '12px' }}>
                  {activity.time}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="card" style={{ marginTop: '40px' }}>
        <h3 style={{ fontSize: '20px', marginBottom: '20px', color: '#64ffda' }}>
          Quick Actions
        </h3>
        <div style={{ display: 'flex', gap: '15px', flexWrap: 'wrap' }}>
          <Link to="/admin/parking" className="btn btn-primary">
            Add Parking Area
          </Link>
          <Link to="/admin/users" className="btn btn-secondary">
            Manage Users
          </Link>
          <button className="btn btn-secondary" onClick={() => alert('QR Scanner opening...')}>
            Scan QR Code
          </button>
          <button className="btn btn-secondary">
            Generate Report
          </button>
          <Link to="/admin/profile" className="btn btn-secondary">
            Profile Settings
          </Link>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
